// input wystrzeliwuje przy KAZDEJ, pojedynczej zmianie wartosci pola
// (wlacznie z wklejaniem tekstu) - idealne do reakcji 'w czasie
// rzeczywistym', np. licznika znakow aktualizowanego podczas pisania.
//
// change wystrzeliwuje DOPIERO gdy wartosc pola zmienila sie ORAZ
// element STRACIL fokus (uzytkownik 'odszedl' od pola) - lepsze, gdy
// nie potrzebujesz reagowac na kazda pojedyncza litere, tylko na
// finalny wynik (np. wybor z listy rozwijanej <select>).

function jestSkrotem(e, klawisz) {
  return e.ctrlKey && e.key === klawisz;
}

console.log(jestSkrotem({ ctrlKey: true, key: "s" }, "s"));
console.log(jestSkrotem({ ctrlKey: false, key: "s" }, "s"));

function policzZnaki(wartosc, limit) {
  return { ile: wartosc.length, przekroczono: wartosc.length > limit };
}

console.log(policzZnaki("Ala ma kota", 20));
console.log(policzZnaki("Ala ma kota i psa, oraz duzo innych zwierzat", 20));

function rozpoznajKlawisz(key) {
  return ["Enter", "Escape", "Tab"].includes(key) ? "nawigacyjny" : "zwykly";
}

console.log(rozpoznajKlawisz("Enter"), rozpoznajKlawisz("a"));

function symulujFokus() {
  return {
    aktywny: null,
    ustawFokus(id) { this.aktywny = id; },
    usunFokus() { this.aktywny = null; }
  };
}

const stan = symulujFokus();
stan.ustawFokus("email");
console.log(stan.aktywny);
stan.usunFokus();
console.log(stan.aktywny);

function waliduj(wartosc) {
  const bledy = [];
  if (wartosc.trim() === "") bledy.push("puste");
  if (wartosc.length > 0 && wartosc.length < 3) bledy.push("za krotkie");
  return bledy;
}

console.log(waliduj(""));
console.log(waliduj("ab"));
console.log(waliduj("Ala"));

function obsluzEnterLubEscape(key, wartosc) {
  if (key === "Enter") return "wyslano: " + wartosc;
  if (key === "Escape") return "";
  return null;
}

console.log(obsluzEnterLubEscape("Enter", "test"));
console.log(obsluzEnterLubEscape("Escape", "test"));
console.log(obsluzEnterLubEscape("a", "test"));

class LicznikZnakow {
  constructor(limit) {
    this.limit = limit;
  }
  sprawdz(wartosc) {
    return this.limit - wartosc.length;
  }
}

const licznik = new LicznikZnakow(10);
console.log(licznik.sprawdz("abc"));
console.log(licznik.sprawdz("dwanascie znakow"));

function symulujZmianeRoli(poprzednia, nowa) {
  return poprzednia !== nowa;
}

console.log(symulujZmianeRoli("user", "admin"));
console.log(symulujZmianeRoli("user", "user"));

function ostatnieNKlawiszy(historia, n) {
  return historia.slice(-n);
}

console.log(ostatnieNKlawiszy(["a", "b", "c", "d"], 2));

function symulujKombinacje(wcisniete) {
  return wcisniete.has("Control") && wcisniete.has("s");
}

console.log(symulujKombinacje(new Set(["Control", "s"])));
console.log(symulujKombinacje(new Set(["Control"])));

function formatujWartosc(wartosc, maxDlugosc) {
  if (wartosc.length <= maxDlugosc) return wartosc;
  return wartosc.slice(0, maxDlugosc) + "...";
}

console.log(formatujWartosc("krotki", 10));
console.log(formatujWartosc("bardzo dlugi tekst", 10));

function kolejnoscFokusu(elementy, aktualny) {
  const idx = elementy.indexOf(aktualny);
  return elementy[(idx + 1) % elementy.length];
}

console.log(kolejnoscFokusu(["imie", "email", "haslo"], "email"));
console.log(kolejnoscFokusu(["imie", "email", "haslo"], "haslo"));

function debounceSymulacja(wartosci) {
  return wartosci[wartosci.length - 1];
}

console.log(debounceSymulacja(["a", "al", "ala", "ala "]));

function maskaTelefonu(cyfry) {
  const czysta = cyfry.slice(0, 9);
  return czysta.match(/.{1,3}/g)?.join(" ") ?? "";
}

console.log(maskaTelefonu("123456789"));
console.log(maskaTelefonu("12345"));

function czyWymaganePolaWypelnione(pola, wymagane) {
  return wymagane.every(nazwa => pola[nazwa]?.trim());
}

console.log(czyWymaganePolaWypelnione({ imie: "Ala", opis: "" }, ["imie"]));
console.log(czyWymaganePolaWypelnione({ imie: "", opis: "cos" }, ["imie"]));

function symulujCapsLock(znak, capsAktywny) {
  return capsAktywny ? znak.toUpperCase() : znak.toLowerCase();
}

console.log(symulujCapsLock("a", true));
console.log(symulujCapsLock("A", false));

function zliczTypyZdarzen(historia) {
  return historia.reduce((acc, typ) => {
    acc[typ] = (acc[typ] || 0) + 1;
    return acc;
  }, {});
}

console.log(zliczTypyZdarzen(["input", "input", "change", "focus"]));

function pierwszeNieprawidlowe(pola, waliduj) {
  return Object.keys(pola).find(nazwa => !waliduj(pola[nazwa]));
}

console.log(pierwszeNieprawidlowe({ imie: "Ala", email: "" }, (v) => v.trim() !== ""));

function symulujTabOrder(pola, aktualnyIndeks, shiftWcisniety) {
  const kierunek = shiftWcisniety ? -1 : 1;
  return (aktualnyIndeks + kierunek + pola.length) % pola.length;
}

console.log(symulujTabOrder(["a", "b", "c"], 0, true));
console.log(symulujTabOrder(["a", "b", "c"], 2, false));

function symulujPasteEvent(dotychczasowa, kursorIdx, wklejony) {
  return dotychczasowa.slice(0, kursorIdx) + wklejony + dotychczasowa.slice(kursorIdx);
}

console.log(symulujPasteEvent("ac", 1, "b"));

function maksymalnaDlugoscHistorii(historia, limit) {
  return historia.length > limit ? historia.slice(-limit) : historia;
}

console.log(maksymalnaDlugoscHistorii(["a", "b", "c", "d", "e"], 3));

function jestPoprawnyKodPocztowy(wartosc) {
  return /^\d{2}-\d{3}$/.test(wartosc);
}

console.log(jestPoprawnyKodPocztowy("00-950"));
console.log(jestPoprawnyKodPocztowy("00950"));

